package integration

import (
	"strings"
	"testing"
)

// Each example is a complete public CLI invocation with independent expected
// output, including nonmatches. No spelling expectations are generated by the
// production library or by its dictionary.
func TestSyntaxContract(t *testing.T) {
	bin := binary(t, "FZFP_BIN", "fzfp")
	for _, tc := range []struct {
		name, input, query, want string
		opts                     []string
	}{
		{"exact-adjacency", "北京\n北小京\n北京市\n", "'bj", "北京\n北京市\n", nil},
		{"exact-final-prefix", "北京\n北小京\n", "'beiji", "北京\n", nil},
		{"prefix", "北京\n北京市\n去北京\n北小京\n  北京\n", "^bj", "北京\n北京市\n  北京\n", nil},
		{"prefix-not-regex", "北京\n", "^b.*j", "", nil},
		{"suffix", "北京\n去北京\n北京市\n北小京\n北京  \n", "bj$", "北京\n去北京\n北京  \n", nil},
		{"suffix-final-prefix", "去北京\n北京市\n", "beiji$", "去北京\n", nil},
		{"suffix-no-syllable-interior", "京\n", "ing$", "", nil},
		{"word-delimited-span", "北京\n去北京\n北京市\n去 北京 好\n北京/文件\n北京_文件\n北京Server\n", "'bj'", "北京\n去 北京 好\n北京/文件\n北京_文件\n", nil},
		{"word-final-prefix", "北京\n北京大学\n", "'beiji'", "北京\n", nil},
		{"inverse-exact", "北京\n北小京\n上海\n", "!bj", "北小京\n上海\n", nil},
		{"inverse-fuzzy", "北京\n北小京\n上海\n", "!'bj", "上海\n", nil},
		{"inverse-prefix", "北京\n北京市\n去北京\n上海\n", "!^bj", "去北京\n上海\n", nil},
		{"inverse-suffix", "北京\n北京市\n去北京\n上海\n", "!bj$", "北京市\n上海\n", nil},
		{"inverse-equal", "北京\n北京市\n去北京\n上海\n", "!^bj$", "北京市\n去北京\n上海\n", nil},
		{"or", "北京\n上海\n北小京\n南京\n", "^bj | ^sh", "北京\n上海\n", nil},
		{"or-and-grouping", "北京大学\n上海大学\n北京小学\n上海小学\n", "^bj | ^sh dx$", "北京大学\n上海大学\n", nil},
		{"and-no-order-requirement", "北京大学\n大学北京\n北京小学\n", "bj dx", "北京大学\n大学北京\n", nil},
		{"escaped-space", "北 京\n北京\n", `b\ j`, "北 京\n", nil},
		{"equal-source-coverage", "北京\n  北京  \n去北京\n北京市\n北小京\n", "^bj$", "北京\n  北京  \n", nil},
		{"equal-final-prefix", "北京\n北京市\n", "^beiji$", "北京\n", nil},
		{"smart-case-pinyin", "北京\nbj\nBJ\n", "BJ", "北京\nBJ\n", nil},
		{"smart-case-mixed", "北京Server\n北京server\nbjServer\nBJServer\n", "BJServer", "北京Server\nBJServer\n", nil},
		{"ignore-case", "北京Server\n北京server\nbjServer\nBJServer\n", "BJServer", "北京Server\n北京server\nbjServer\nBJServer\n", []string{"-i"}},
		{"respect-case-pinyin", "北京Go\n北京go\nBJGo\nbjGo\n", "BJGo", "北京Go\nBJGo\n", []string{"+i"}},
		{"respect-case-negative", "北京Server\n北京server\n", "BJSERVER", "", []string{"+i"}},
		{"exact-option", "北京\n北小京\n", "bj", "北京\n", []string{"--exact"}},
		{"exact-option-unquote", "北京\n北小京\n", "'bj", "北京\n北小京\n", []string{"--exact"}},
		{"no-extended", "北京\n北小京\n", "'bj", "", []string{"+x"}},
		{"literal-does-not-disable-pinyin", "北京\n北京é\n北京e\n", "bj", "北京\n北京é\n北京e\n", []string{"--literal"}},
		{"literal-accents", "北京é\n北京e\n", "bje", "北京e\n", []string{"--literal"}},
		{"default-accents", "北京é\n北京e\n", "bje", "北京é\n北京e\n", nil},
		{"literal-umlaut", "女绿\n", "NÜLÜ", "女绿\n", []string{"--literal"}},
		{"field-prefix", "id:北京\nbj:上海\nid:去北京\n", "^bj", "id:北京\n", []string{"--delimiter=:", "--nth=2"}},
		{"field-suffix", "id:北京:tag\nid:北京市:tag\n", "bj$", "id:北京:tag\n", []string{"--delimiter=:", "--nth=2"}},
		{"field-equal", "id:北京:tag\nid:北京市:tag\n", "^bj$", "id:北京:tag\n", []string{"--delimiter=:", "--nth=2"}},
		{"field-independent-ranges", "北:京\n", "bj", "", []string{"--delimiter=:", "--nth=1,2"}},
		{"field-contiguous-range", "北:京\n", "bj", "北:京\n", []string{"--delimiter=:", "--nth=1..2"}},
		{"delimiter-is-not-query-separator", "北京:上海\n", "bj:sh", "北京:上海\n", []string{"--delimiter=:"}},
		{"unicode-delimiter-regex", "id：北京，tag\nid：上海，tag\n", "^bj$", "id：北京，tag\n", []string{"--delimiter=[：，]", "--nth=2"}},
		{"algo-v1-phonetic", "北京\n北小京\n上海\n", "beiji", "北京\n北小京\n", []string{"--algo=v1"}},
		{"scheme-default", "北京\n北小京\n上海\n", "bj", "北京\n北小京\n", []string{"--scheme=default"}},
		{"scheme-path", "北京\n北小京\n上海\n", "bj", "北京\n北小京\n", []string{"--scheme=path"}},
		{"scheme-history", "北京\n北小京\n上海\n", "bj", "北京\n北小京\n", []string{"--scheme=history"}},
	} {
		t.Run(tc.name, func(t *testing.T) {
			args := append(append([]string{}, tc.opts...), "--no-sort", "--filter", tc.query)
			got := filter(t, bin, tc.input, args...)
			code := 0
			if tc.want == "" {
				code = 1
			}
			if got.stdout != tc.want || got.code != code || got.stderr != "" {
				t.Fatalf("args=%q got=%+v want stdout=%q code=%d", args, got, tc.want, code)
			}
		})
	}
}

func TestPinyinTiebreakSyntax(t *testing.T) {
	bin := binary(t, "FZFP_BIN", "fzfp")
	// Same source-position evidence and same score; length/index operate on
	// the original candidate, without inventing pinyin expansion lengths.
	input := "北京很长后缀\n北京\n北京短\n"
	for _, tc := range []struct{ option, want string }{
		{"length", "北京\n北京短\n北京很长后缀\n"},
		{"index", input},
		{"begin,length", "北京\n北京短\n北京很长后缀\n"},
		{"chunk,length", "北京\n北京短\n北京很长后缀\n"},
	} {
		got := filter(t, bin, input, "--tiebreak="+tc.option, "--filter=bj")
		if got.stdout != tc.want || got.code != 0 {
			t.Fatalf("%s: %+v", tc.option, got)
		}
	}
	for _, scheme := range []string{"default", "path", "history"} {
		args := []string{"--scheme=" + scheme, "--filter=bj"}
		got := filter(t, bin, input, args...)
		want := "北京\n北京短\n北京很长后缀\n"
		if scheme == "history" {
			want = input
		}
		if got.stdout != want {
			t.Fatalf("scheme=%s: %+v", scheme, got)
		}
	}
}

func TestXdaoContiguousRanking(t *testing.T) {
	bin := binary(t, "FZFP_BIN", "fzfp")
	for _, input := range []string{"文化宣导员会议\n小一二三四道\n", "小一二三四道\n文化宣导员会议\n"} {
		got := filter(t, bin, input, "--filter=xdao")
		if got.code != 0 || got.stdout != "文化宣导员会议\n小一二三四道\n" {
			t.Fatalf("%+v", got)
		}
	}
}

func TestUppercaseNonHanParity(t *testing.T) {
	bin, ref := binary(t, "FZFP_BIN", "fzfp"), binary(t, "FZF_REFERENCE_BIN", "fzf-reference")
	input := "bj\nBJ\nBj\nbjServer\nBJServer\nBJserver\nécole\nÉcole\nfooBar\n"
	for _, q := range []string{"BJ", "bj", "Bj", "BJServer", "'BJ", "^BJ", "BJ$", "'BJ'", "!BJ", "!^BJ", "!BJ$", "^BJ$", "BJ | fooBar"} {
		for _, options := range [][]string{nil, {"-i"}, {"+i"}, {"--exact"}, {"--literal"}, {"--algo=v1"}} {
			args := append(append([]string{}, options...), "--filter", q)
			got, want := filter(t, bin, input, args...), filter(t, ref, input, args...)
			if got != want {
				t.Fatalf("args=%s got=%+v want=%+v", strings.Join(args, " "), got, want)
			}
		}
	}
}
